import pytest

from bedrock_protocol import v1001, v2168, v2225

PRIORITY = v2225.CameraAimAssistActorPriority.PriorityData

# generated by gophertunnel b8bd735:
# &packet.CameraAimAssistActorPriority{PriorityData: []protocol.CameraAimAssistActorPriorityData{{PresetIndex: 1,
# CategoryIndex: 2, ActorIndex: 3, Priority: -4}}}
ACTOR_PRIORITY = bytes.fromhex("01010000000200000003000000fcffffff")

GOLDENS = [
    pytest.param(
        v2225.CameraAimAssistActorPriorityPacket(
            camera_aim_assist_actor_priority_list=[
                PRIORITY(preset_index=1, category_index=2, actor_index=3, priority_value=-4)
            ]
        ),
        ACTOR_PRIORITY,
        id="one-entry",
    ),
]

NEGATIVE_INDEX = v2225.CameraAimAssistActorPriorityPacket(
    camera_aim_assist_actor_priority_list=[PRIORITY(preset_index=-1, category_index=0, actor_index=0, priority_value=0)]
)


@pytest.mark.parametrize("version", [v1001, v2168], ids=lambda version: version.__name__.rpartition(".")[2])
def test_camera_aim_assist_actor_priority_is_packet_339(version):
    assert version.PACKETS[339] is version.CameraAimAssistActorPriorityPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_camera_aim_assist_actor_priority_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_camera_aim_assist_actor_priority_decodes_from_its_golden(packet, golden):
    assert v2225.CameraAimAssistActorPriorityPacket.from_bytes(golden) == packet


def test_a_negative_index_stays_four_bytes():
    assert len(bytes(NEGATIVE_INDEX)) == 17


def test_a_negative_index_round_trips():
    assert v2225.CameraAimAssistActorPriorityPacket.from_bytes(bytes(NEGATIVE_INDEX)) == NEGATIVE_INDEX
